on"}, {"id": "25480365-2bf7-4ed8-867c-59a71da70fdc", "type": "concept", "title": "Cartels"}, {"id": "cb524c3a-e99f-48e5-8fee-6064da7ef700", "type": "concept", "title": "Entry deterrence"}, {"id": "b45bf5e3-4e33-4d40-8494-d889d2017178", "type": "concept", "title": "Strategic commitment"}], "description": "Oligopoly analysis explains market power beyond simple monopoly."}]}, {"id": "815d491b-6afd-4fcd-b59d-f9340d4ea90e", "type": "topic", "title": "General Equilibrium and Welfare", "description": "Connect markets into an economy-wide system and evaluate efficiency and distribution.", "children": [{"id": "1c5650eb-bbb6-4a1d-bf92-27e17c8ab00c", "type": "subtopic", "title": "Exchange economy", "children": [{"id": "cc5e866b-1eb2-4db4-8984-e6b6da0b4906", "type": "concept", "title": "Edgeworth box"}, {"id": "123b10b0-5121-4c68-8471-230b49430501", "type": "concept", "title": "Contract curve"}, {"id": "0f6c7b76-f2d2-4866-be8c-40723192a91c", "type": "concept", "title": "Pareto efficiency"}, {"id": "5ee65e69-6d52-46d9-8dd7-f25bc61599fc", "type": "concept", "title": "Competitive equilibrium"}], "description": "General equilibrium shows how markets interact rather than clearing one at a time."}, {"id": "b44f3591-c9da-48a1-9568-cd3075147764", "type": "subtopic", "title": "Welfare theorems", "children": [{"id": "459b1288-e671-4859-9b4b-436df6030743", "type": "concept", "title": "First welfare theorem"}, {"id": "b3c00bb8-c28f-4ebd-bf71-595cc700e4b4", "type": "concept", "title": "Second welfare theorem"}, {"id": "2b2791e3-b074-4fb0-9a19-118819a52d76", "type": "concept", "title": "Efficiency vs equity"}, {"id": "79adb87e-e08c-45b5-b115-8d8253903a51", "type": "concept", "title": "Missing markets"}], "description": "Welfare theorems clarify when markets allocate efficiently and what assumptions matter."}, {"id": "1b67359b-6415-4b33-8bd2-84241cf15652", "type": "subtopic", "title": "Distribution and social welfare", "children": [{"id": "10ebe220-b333-4896-a335-6510c619faa8", "type": "concept", "title": "Social welfare functions"}, {"id": "e9790db1-a557-4ee5-ab04-d9429bd46075", "type": "concept", "title": "Equity-efficiency tradeoff"}, {"id": "4bd6766f-a197-41c0-ab3b-beaadcde354a", "type": "concept", "title": "Compensation tests"}, {"id": "1bf75ce3-4146-4e40-a70c-11c22def83f7", "type": "concept", "title": "Policy incidence"}], "description": "Welfare analysis requires explicit value judgments about distribution."}]}, {"id": "eaefef82-fe31-4cba-bc35-abc441bb852c", "type": "topic", "title": "Asymmetric Information and Market Failure", "description": "Explain how hidden information, externalities, and public goods can prevent efficient outcomes.", "children": [{"id": "9719de56-6cf3-48f6-90fa-e7aabb233c98", "type": "subtopic", "title": "Externalities and public goods", "children": [{"id": "0f3202d1-e237-4cac-8bb7-c910a316d5b9", "type": "concept", "title": "Negative externalities"}, {"id": "56b01395-1397-40ab-b864-d2ccb4c49d60", "type": "concept", "title": "Positive externalities"}, {"id": "db99e954-afce-4121-8b33-8de6de49af94", "type": "concept", "title": "Public goods"}, {"id": "c4333618-63cb-435c-8a92-ef4754b518ca", "type": "concept", "title": "Free riding"}], "description": "Some costs and benefits are not captured in market prices."}, {"id": "f33a01d9-97db-4d2f-adb0-f848801f3874", "type": "subtopic", "title": "Hidden information", "children": [{"id": "61f2d645-590f-4c3b-978d-ecc04756c872", "type": "concept", "title": "Lemons problem"}, {"id": "8fd2b05e-7cae-484e-a910-a6051c6cd726", "type": "concept", "title": "Screening"}, {"id": "f1ae6035-dd23-4d72-9281-3a390d9f1f1b", "type": "concept", "title": "Signaling"}, {"id": "624bc762-65f2-45c7-91cc-c7de19e82c7e", "type": "concept", "title": "Market unraveling"}], "description": "Adverse selection occurs when one side knows more before a transaction."}, {"id": "84e341ad-2b42-4485-871b-1a5fdd084910", "type": "subtopic", "title": "Hidden action", "children": [{"id": "669a9663-9423-473f-9117-231ce773fc10", "type