  data = $imicjson${"slug": "intermediate-microeconomics", "title": "Intermediate Microeconomics", "description": "This syllabus covers the intermediate microeconomics core. It includes risk/intertemporal choice, mechanism design and auctions, industrial organization and competition policy, and behavioral/empirical applications so students can move from clean models to modern evidence and institutional design.", "topics": [{"id": "71da898e-846e-4d84-82b5-8d315b173d35", "type": "topic", "title": "Consumer Theory: Budget Constraints and Preferences", "description": "Model how consumers rank bundles and face tradeoffs under scarce income and prices.", "children": [{"id": "ffb1940b-98dc-477a-9456-8f321be88bd3", "type": "subtopic", "title": "Budget sets", "children": [{"id": "36060e97-c97a-47dd-bdca-bf28b113da3a", "type": "concept", "title": "Budget line"}, {"id": "365432f8-d624-4bbd-a5cc-0738851cfe6e", "type": "concept", "title": "Relative prices"}, {"id": "0d283d96-f200-4e92-8d27-9ed0862022ff", "type": "concept", "title": "Opportunity cost"}, {"id": "1228111c-edb6-4906-aaf5-cdc9ac51b557", "type": "concept", "title": "Changes in income and prices"}], "description": "Budget sets show the feasible choices created by income and prices."}, {"id": "ab27866a-43ce-46c5-9f94-433d192db85f", "type": "subtopic", "title": "Preference assumptions", "children": [{"id": "953139e3-4fe6-4a10-8379-03c7b445361d", "type": "concept", "title": "Completeness"}, {"id": "ddead972-7cef-4c29-b3ec-de318ee27805", "type": "concept", "title": "Transitivity"}, {"id": "c43afc50-e832-4883-9cbc-bee89df87de5", "type": "concept", "title": "Monotonicity"}, {"id": "9ae4970f-4cb2-4a63-8f20-f39c02b8f235", "type": "concept", "title": "Convexity"}], "description": "Preference assumptions give the model enough structure to make predictions."}, {"id": "94c87fe2-7759-46b7-a42a-4863bb1d92ea", "type": "subtopic", "title": "Indifference curves", "children": [{"id": "2824cc7b-9d8f-4aec-8b88-0ac229a745d3", "type": "concept", "title": "Marginal rate of substitution"}, {"id": "089253c1-2730-4e82-acab-c0ec8a3ac21e", "type": "concept", "title": "Perfect substitutes"}, {"id": "1c0f8b70-dcdb-4793-9e64-af4c7c05708b", "type": "concept", "title": "Perfect complements"}, {"id": "5e62cd5a-62f9-4f8b-9632-de168a0cb27c", "type": "concept", "title": "Cobb-Douglas preferences"}], "description": "Indifference curves visualize tradeoffs and marginal willingness to substitute."}]}, {"id": "dc6adb9b-7ef7-40a2-8de2-bc64435461ab", "type": "topic", "title": "Utility Maximization and Demand", "description": "Derive individual demand from preferences, constraints, and optimization.", "children": [{"id": "38ac2f4e-544f-4152-aa95-6b9734c19d09", "type": "subtopic", "title": "Constrained optimization", "children": [{"id": "577f1160-581f-4b9e-a0bb-a0f38fe5af73", "type": "concept", "title": "Tangency condition"}, {"id": "6650b832-de06-45ba-8fd5-622af433260f", "type": "concept", "title": "Corner solutions"}, {"id": "a44e6f27-9896-4bd4-a0d7-c75e2d340efb", "type": "concept", "title": "Lagrange method overview"}, {"id": "3dc064d3-2e99-404f-b915-0525293400ca", "type": "concept", "title": "Marshallian demand"}], "description": "Optimization turns preferences and budgets into a chosen bundle."}, {"id": "72aa8ca1-47a0-4bda-81a4-514fc46c00ae", "type": "subtopic", "title": "Demand responses", "children": [{"id": "603212cd-4a07-47d9-9a51-a958e3d36c78", "type": "concept", "title": "Income effects"}, {"id": "88a09ccd-56ac-433a-ab83-bc71dd0ad8b3", "type": "concept", "title": "Substitution effects"}, {"id": "1a901117-5eed-4551-83c2-0f40d8b95fe4", "type": "concept", "title": "Normal goods"}, {"id": "9f463e53-d77d-4e0b-9b79-0e3ab3785cef", "type": "concept", "title": "Inferior goods"}], "description": "Demand analysis separates how consumers respond to price and income changes."}, {"id": "62f15786-bc90-4e2a-b6b1-f012cbffe018", "type": "subtopic", "title": "Elasticity and aggregation", "children": [{"id": "401f0da3-27ac-41ec-8b16